def solve():
    edges = []
    # Cliques
    for g in range(4):
        edges.append((g*2 + 0, g*2 + 1))
    # Connections
    for g in range(3):
        for i in range(2):
            edges.append((g*2 + i, (g+1)*2 + i))

    print("Edges:", edges)

    def search(idx, current_labels, used_labels, used_diffs):
        if idx == 8:
            return current_labels

        for l in range(11):
            if l in used_labels:
                continue

            # Check if we can assign l to vertex idx
            valid = True
            new_diffs = []
            for u, v in edges:
                if u == idx and v < idx:
                    diff = abs(l - current_labels[v])
                    if diff in used_diffs or diff in new_diffs:
                        valid = False
                        break
                    new_diffs.append(diff)
                elif v == idx and u < idx:
                    diff = abs(l - current_labels[u])
                    if diff in used_diffs or diff in new_diffs:
                        valid = False
                        break
                    new_diffs.append(diff)

            if valid:
                used_labels.add(l)
                for d in new_diffs:
                    used_diffs.add(d)
                current_labels.append(l)

                res = search(idx + 1, current_labels, used_labels, used_diffs)
                if res:
                    return res

                current_labels.pop()
                for d in new_diffs:
                    used_diffs.remove(d)
                used_labels.remove(l)

    return search(0, [], set(), set())

print(solve())
